	private CanonicalStagedInput stageDependencyInputs(Path stagedDirectory, int partitionCount, int targetCount,
			SimpleValueFactory valueFactory, IRI predicate, IRI datatype, LmdbStoreConfig config,
			BulkCompression compression, long memoryBudgetBytes, int maxOpenFiles) throws Exception {
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(stagedDirectory, config, partitionCount,
				maxOpenFiles, memoryBudgetBytes, compression)) {
			int valuesInPartitionZero = 0;
			for (int candidate = 0; valuesInPartitionZero < targetCount; candidate++) {
				IRI subject = valueFactory.createIRI("urn:dependency:subject:" + candidate);
				byte[] key = CanonicalTermCodec.encode(subject);
				if (((int) CanonicalTermCodec.routeHash64(key) & (partitionCount - 1)) != 0) {
					continue;
				}
				var literal = valueFactory.createLiteral("object-" + candidate, datatype);
				var object = valuesInPartitionZero % 16 == 0
						? valueFactory.createTripleTerm(subject, predicate,
								valueFactory.createLiteral("quoted-" + valuesInPartitionZero % 4, datatype))
						: literal;
				stager.writeStatement(valueFactory.createStatement(subject, predicate, object));
				valuesInPartitionZero++;
			}
			staged = stager.stagedInput();
		}
		return staged;
	}

	private static int rolesForKey(PartitionValueDictionary dictionary, byte[] key) throws IOException {
		int[] roles = { 0 };
		dictionary.forEachEntry(entry -> {
			if (Arrays.equals(key, entry.key())) {
				roles[0] = entry.roles();
			}
		});
		return roles[0];
	}

	private static List<String> dictionaryEntries(PartitionValueDictionary dictionary) throws IOException {
		List<String> entries = new ArrayList<>();
		dictionary.forEachEntry(entry -> entries.add(entry.partition() + ":" + entry.id() + ":" + entry.roles() + ":"
				+ HexFormat.of().formatHex(entry.key())));
		return entries;
	}

	private static List<String> dependencyEntries(ValueDependencyBuckets dependencies, int partitionCount)
			throws IOException {
		List<String> entries = new ArrayList<>();
		for (int partition = 0; partition < partitionCount; partition++) {
			int partitionId = partition;
			dependencies.forEachPartitionValue(partitionId,
					(ignored, routeHash, roles, key) -> entries.add(partitionId + ":"
							+ routeHash + ":" + roles + ":" + HexFormat.of().formatHex(key)));
		}
		return entries;
	}
